import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_CUDA_SRC = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>
#include <cuda_bf16.h>
#include <cublas_v2.h>
#include <cstdint>
#include <iostream>

#define CUDA_CHECK(call) do { \
  cudaError_t err = (call); \
  if (err != cudaSuccess) { \
    std::cerr << "CUDA error: " << cudaGetErrorString(err) << " at " << __FILE__ << ":" << __LINE__ << std::endl; \
    throw std::runtime_error("CUDA error"); \
  } \
} while (0)

#define CUBLAS_CHECK(call) do { \
  cublasStatus_t st = (call); \
  if (st != CUBLAS_STATUS_SUCCESS) { \
    std::cerr << "cuBLAS error: " << int(st) << " at " << __FILE__ << ":" << __LINE__ << std::endl; \
    throw std::runtime_error("cuBLAS error"); \
  } \
} while (0)

static cublasHandle_t get_handle() {
  static cublasHandle_t handle = nullptr;
  if (handle == nullptr) {
    CUBLAS_CHECK(cublasCreate(&handle));
    CUBLAS_CHECK(cublasSetMathMode(handle, CUBLAS_TENSOR_OP_MATH));
  }
  return handle;
}

void run_gemm_h100_cublas(int64_t A_ptr, int64_t B_ptr, int64_t C_ptr,
                          int M, int K, int N) {
  const void* A = reinterpret_cast<const void*>(A_ptr);
  const void* B = reinterpret_cast<const void*>(B_ptr);
  void* C = reinterpret_cast<void*>(C_ptr);

  cublasHandle_t handle = get_handle();
  CUBLAS_CHECK(cublasSetStream(handle, at::cuda::getCurrentCUDAStream()));

  const float alpha = 1.0f;
