__device__ inline void ldmatrix_x2(uint32_t reg[2], uint32_t addr){ asm volatile("ldmatrix.sync.aligned.m8n8.x2.shared.b16 {%0,%1}, [%2];":"=r"(reg[0]),"=r"(reg[1]):"r"(addr)); }
